//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_reflect_set_same_receiver_scalar_raw_and_native_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});if(!Reflect.set(d,'first','one')||!Reflect.set(d,'x\ud800Name','raw\udfff',d)||!Reflect.set(d,'omitted'))throw 'native true results';var records=watch.takeRecords();if(d.first!=='one'||d['x\ud800Name']!=='raw\udfff'||d.omitted!=='undefined'||records.length!==3||records[1].attributeName!=='data-x\ud800-name'||records[1].oldValue!==null||records[1].target!==n)throw 'native exact observed reflection';"#);}

#[test]
fn dataset_reflect_set_different_ordinary_receiver_preserves_value_and_ignores_native_names(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,out={},value={toString:function(){throw 'must not bind';}};d['x\ud800']='native';if(!Reflect.set(d,'x\ud800',value,out)||out['x\ud800']!==value||d['x\ud800']!=='native'||Object.keys(d).length!==1)throw 'different receiver ignores native named properties';var desc=Object.getOwnPropertyDescriptor(out,'x\ud800');if(!desc.writable||!desc.enumerable||!desc.configurable)throw 'ordinary receiver flags';"#);}

#[test]
fn dataset_reflect_set_ordinary_and_other_dataset_targets_write_native_receiver(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,other=document.createElement('p').dataset,source={key:'source'};if(!Reflect.set(source,'key','native',d)||d.key!=='native'||source.key!=='source')throw 'ordinary target native receiver';if(!Reflect.set(other,'x\ud800','raw\udfff',d)||d['x\ud800']!=='raw\udfff'||other['x\ud800']!==undefined)throw 'different dataset receiver';var frozen={};Object.defineProperty(frozen,'denied',{value:1,writable:false});if(Reflect.set(frozen,'denied','bad',d)!==false||d.denied!==undefined)throw 'ordinary readonly before native receiver';"#);}

#[test]
fn dataset_reflect_set_different_primitive_and_frozen_receivers_return_false_without_binding(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,hits=0,value={toString:function(){hits++;return 'bad';}};for(var receiver of [undefined,null,1,true,'text'])if(Reflect.set(d,'x\ud800',value,receiver)!==false)throw 'primitive receiver';var frozen={};Object.preventExtensions(frozen);if(Reflect.set(d,'x\ud800',value,frozen)!==false||hits||Object.keys(d).length)throw 'frozen receiver without native binding';"#);}

#[test]
fn dataset_reflect_set_different_receiver_observes_prototype_setters_and_readonly_descriptors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,out={},value={},seen,seenThis;d['x\ud800']='native';Object.defineProperty(DOMStringMap.prototype,'x\ud800',{set:function(v){seen=v;seenThis=this;},configurable:true});if(!Reflect.set(d,'x\ud800',value,out)||seen!==value||seenThis!==out||Object.hasOwn(out,'x\ud800')||d['x\ud800']!=='native')throw 'different receiver genuine prototype setter';Object.defineProperty(DOMStringMap.prototype,'readonly',{get:function(){throw 'getter';},configurable:true});if(Reflect.set(d,'readonly',value,out)!==false||Object.hasOwn(out,'readonly'))throw 'getter-only descriptor false';if(!Reflect.set(d,'readonly','native',d)||d.readonly!=='native')throw 'same receiver bypasses prototype';"#);}

#[test]
fn dataset_reflect_set_key_then_value_binding_and_native_invalid_name_errors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,order='',key={toString:function(){order+='K';return 'bad\ud800-key';}},value={toString:function(){order+='V';return 'value';}},caught;try{Reflect.set(d,key,value);}catch(e){caught=e;}if(order!=='KV'||!(caught instanceof DOMException)||caught.name!=='SyntaxError'||Object.keys(d).length)throw 'key then WebIDL binding then native validation';order='';if(!Reflect.set(d,{toString:function(){order+='K';return 'x\ud800';}},{toString:function(){order+='V';return 'raw\udfff';}})||order!=='KV'||d['x\ud800']!=='raw\udfff')throw 'once-only key/value binding';"#);}

#[test]
fn dataset_reflect_set_author_abrupt_identity_and_side_effects_are_preserved(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,marker={},caught,hits=0;try{Reflect.set(d,{toString:function(){d.side='key';throw marker;}},{toString:function(){hits++;return 'bad';}});}catch(e){caught=e;}if(caught!==marker||hits||d.side!=='key')throw 'key abrupt before value';caught=undefined;try{Reflect.set(d,'x\ud800',{toString:function(){d.side='value';throw marker;}});}catch(e){caught=e;}if(caught!==marker||d.side!=='value'||d['x\ud800']!==undefined)throw 'value abrupt effect identity';caught=undefined;try{Reflect.set(d,'symbolValue',Symbol('bad'));}catch(e){caught=e;}if(!(caught instanceof TypeError)||d.symbolValue!==undefined)throw 'native Symbol value rejection';"#);}

#[test]
fn dataset_reflect_set_html_svg_native_names_and_shadow_bypass(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset,hits=0;n.setAttribute=function(){hits++;throw 'shadow';};Object.defineProperty(DOMStringMap.prototype,'x\ud800Name',{set:function(){hits++;throw 'prototype';},configurable:true});if(!Reflect.set(d,'x\ud800Name','native')||hits||n.getAttributeNS(null,'data-x\ud800-name')!=='native'||d['x\ud800Name']!=='native')throw 'genuine HTML SVG same receiver';}"#);}

#[test]
fn dataset_reflect_set_different_proxy_receiver_preserves_raw_key_and_descriptor_protocol(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,out={},order='',value={},handler={};Object.defineProperty(handler,'getOwnPropertyDescriptor',{get:function(){order+='G';return undefined;}});Object.defineProperty(handler,'defineProperty',{get:function(){order+='D';return undefined;}});var proxy=new Proxy(out,handler);if(!Reflect.set(d,'x\ud800',value,proxy)||out['x\ud800']!==value||order!=='GD'||Object.keys(d).length)throw 'native target ordinary proxy receiver protocol';"#);}

#[test]
fn dataset_reflect_set_resource_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var n=document.getElementById('target'),data=n.dataset,big='{}';var watch=new MutationObserver(function(){{}});watch.observe(n,{{attributes:true}});"#,"refused".repeat(200)));let limit=p.state.retained_limit;for mode in 0..4{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.retained_limit=p.state.retained,2=>p.state.host_work=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(r#"Reflect.set(data,'x\ud800',big);"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(["string work","retained","DOM work","computation time"][mode]),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||Object.keys(data).length)throw 'refused Reflect.set changed native state';if(!Reflect.set(data,'recovered','yes')||data.recovered!=='yes'||watch.takeRecords().length!==1)throw 'Reflect.set recovery';delete data.recovered;watch.takeRecords();"#);}}

#[test]
fn dataset_reflect_set_existing_unsupported_proxy_traps_refuse_without_mutation_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset,out={},handler={},proxy=new Proxy(out,handler),ordinary={},hits=0;var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});"#);for trap in ["getOwnPropertyDescriptor","defineProperty"]{run(&mut d,&mut f,&mut p,&format!("handler.{trap}=function(){{hits++;throw 'unsupported trap invoked';}};"));let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for target in ["ordinary","data"]{p.begin_job();let error=p.runtime.execute(&format!(r#"Reflect.set({target},'x\ud800',99,proxy);"#),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(&format!("{trap} trap is not implemented")),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}run(&mut d,&mut f,&mut p,&format!(r#"delete handler.{trap};if(hits||watch.takeRecords().length||Object.keys(out).length||Object.keys(data).length)throw 'unsupported proxy trap changed state';if(!Reflect.set(data,'x\ud800',17,proxy)||out['x\ud800']!==17||Object.keys(data).length)throw 'forwarding recovery';delete out['x\ud800'];"#));}}
